static HAL_StatusTypeDef UART_Receive_IT(UART_HandleTypeDef *huart)
{
  /* Simplified UART receive in interrupt mode for emulation */
  /* Skip all hardware register access and use HAL_BE_In instead */

  /* Check that a Rx process is ongoing */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Calculate how many bytes to read */
    uint16_t bytes_to_read = 1; /* Typically read one byte at a time in interrupt mode */

    /* Use HAL_BE_In to read data from stdin */
    int bytes_read = HAL_BE_In(huart->pRxBuffPtr, bytes_to_read);

    if (bytes_read > 0)
    {
      /* Update buffer pointer */
      if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
      {
        /* For 9-bit data, advance by 2 bytes */
        huart->pRxBuffPtr += 2U;
      }
      else
      {
        /* For 8-bit data, advance by 1 byte */
        huart->pRxBuffPtr += 1U;
      }

      /* Decrement transfer count */
      if (huart->RxXferCount > 0)
      {
        huart->RxXferCount--;
      }

      /* Check if reception is complete */
      if (huart->RxXferCount == 0U)
      {
        /* Rx process is completed, restore huart->RxState to Ready */
        huart->RxState = HAL_UART_STATE_READY;

        /* Initialize type of RxEvent to Transfer Complete */
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Check current reception Mode */
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          /* Set reception type to Standard */
          huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx Event callback*/
          if (huart->RxEventCallback != NULL)
          {
            huart->RxEventCallback(huart, huart->RxXferSize);
          }
#else
          /*Call legacy weak Rx Event callback*/
          HAL_UARTEx_RxEventCallback(huart, huart->RxXferSize);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
        else
        {
          /* Standard reception API called */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx complete callback*/
          if (huart->RxCpltCallback != NULL)
          {
            huart->RxCpltCallback(huart);
          }
#else
          /*Call legacy weak Rx complete callback*/
          HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
      }

      return HAL_OK;
    }
    else
    {
      /* No data available or error */
      return HAL_ERROR;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}
